// Full current app + one original disposable PG database/two owning pools.
// Operator JWT/local RBAC and Node signatures are inputs, NOT external issuer
// enrollment, browser login, managed keys, productive dispatch or teardown.
type Owner = Awaited<ReturnType<typeof dependencyOperator>>;
type Registration = Awaited<ReturnType<Owner['register']>>;
type State = Awaited<ReturnType<Owner['state']>>;
const record = z.record(z.string(), z.unknown());
function restPath(rest: { path: string } | undefined) { assert.ok(rest, 'Original public REST binding required'); return rest.path; }
it('native public registration status refuses an absent committed key without false audit and admits only a fresh original persistence retry', async () => {
	const f = await dependencyOperator();
	try {
		const credential = await f.token(), rest = CONTROL_PLANE_OPERATIONS.providers.registrationCode.status.descriptor.rest; assert.ok(rest);
		const path = rest.path.replace('{teamId}', 'team');
		const get = () => f.app.request(new Request(`https://localhost${path}`, { headers: { authorization: `Bearer ${credential}` } }));
		const baseline = await f.state(); expect(await f.state(f.right)).toEqual(baseline);
		await f.left.pool.query("CREATE FUNCTION registration_key_absence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$");
		await f.left.pool.query("CREATE TRIGGER registration_key_absence BEFORE INSERT ON team_capacity_registration_keys FOR EACH ROW WHEN (NEW.team_id='team') EXECUTE FUNCTION registration_key_absence()");
		await denied(await get(), 404, 'registration_key_missing');
		expect(await f.state()).toEqual(baseline); expect(await f.state(f.right)).toEqual(baseline);
		await f.left.pool.query('DROP TRIGGER registration_key_absence ON team_capacity_registration_keys');
		await f.left.pool.query('DROP FUNCTION registration_key_absence()');
		expect((await f.right.pool.query("SELECT tgname FROM pg_trigger WHERE tgname='registration_key_absence'")).rows).toEqual([]);
		expect((await f.right.pool.query("SELECT proname FROM pg_proc WHERE proname='registration_key_absence'")).rows).toEqual([]);
		const response = await get(); expect(response.status).toBe(200);
		const result = CONTROL_PLANE_OPERATIONS.providers.registrationCode.status.schema.output.parse(await response.json());
		expect(z.object({ teamId: z.literal('team'), generation: z.literal(1) }).parse(result.data)).toEqual({ teamId: 'team', generation: 1 });
		const committed = await f.state(); unchangedExcept(baseline, committed, ['team_capacity_registration_keys', 'capacity_audit_events']);
		expect(additions(baseline, committed, 'team_capacity_registration_keys', 1)[0]).toMatchObject({ team_id: 'team', generation: 1, status: 'active' });
		expect(additions(baseline, committed, 'capacity_audit_events', 1)[0]).toMatchObject({ action: 'registration-key.created', team_id: 'team' });
		const replay = await get(); expect(replay.status).toBe(200); expect(await replay.json()).toEqual(result);
		expect(await f.state()).toEqual(committed); expect(await f.state(f.right)).toEqual(committed);
	} finally { await f.close(); }
});
function registeredProviderId(registration: Registration) {
	const fingerprint = z.string().regex(/^sha256:[A-Za-z0-9_-]{43}$/u).parse(registration.inputs.payload.providerFingerprint);
	const expected = `provider_${fingerprint.slice('sha256:'.length, 'sha256:'.length + 32)}`;
	expect(registration.request.providerId).toBe(expected); return expected;
}
function originalAuditId(action: string, resourceId: string, providerId: string, metadata: Record<string, unknown>) {
	return sha256(`${action}:${action === 'provider-identity.rotated' ? `${providerId}:team:${metadata.identityVersion}` : resourceId}`);
}
const rows = (state: State, table: string) => { expect(state).toHaveProperty(table); return state[table]!.map(value => record.parse(value)); };
function unchangedExcept(before: State, after: State, tables: string[]) {
	expect(Object.keys(after)).toEqual(Object.keys(before)); for (const table of Object.keys(before)) if (!tables.includes(table)) expect(after[table], table).toEqual(before[table]);
}
function additions(before: State, after: State, table: string, count: number) {
	const old = rows(before, table), current = rows(after, table); expect(current).toHaveLength(old.length + count);
	for (const value of old) expect(current).toContainEqual(value);
	return current.filter(value => !old.some(previous => JSON.stringify(previous) === JSON.stringify(value)));
}
function changedRow(before: State, after: State, table: string, id: string, changes: Record<string, unknown>, columns: string[]) {
	const old = rows(before, table), current = rows(after, table); expect(current).toHaveLength(old.length);
	const previous = old.find(row => row.id === id), changed = current.find(row => row.id === id); expect(previous).toBeDefined(); expect(changed).toBeDefined(); expect(changed).toMatchObject(changes);
	for (const value of old) if (value.id !== id) expect(current).toContainEqual(value);
	for (const [column, value] of Object.entries(previous!)) if (!columns.includes(column)) expect(changed![column], column).toEqual(value);
}
async function output(response: Response, operation: typeof CONTROL_PLANE_OPERATIONS.providers.exchangeCredential | typeof CONTROL_PLANE_OPERATIONS.providers.issueAccessToken) {
	expect(response.status).toBe(200); const envelope = z.object({ data: z.unknown() }).parse(await response.json()); return operation.schema.output.parse(envelope.data);
}
async function denied(response: Response, status: number, code: string) { expect(response.status).toBe(status); expect(await response.json()).toMatchObject({ status, code }); }
async function approved(f: Owner) {
	const registration = await f.register(), body = { teamAlias: 'genuinely-enrolled-provider' }, key = 'bootstrap-approved';
	const confirmation = await f.challenge(registration.approvalPath, registration.credential, body, key);
	const response = await f.post(registration.approvalPath, registration.credential, body, key, encodeConfirmation(confirmation)); expect(response.status).toBe(200);
	const result = z.object({ data: z.object({ id: z.string(), providerId: z.string(), membershipId: z.string(), status: z.literal('approved') }) }).parse(await response.json()).data;
	expect(result).toMatchObject({ id: registration.request.id, providerId: registration.request.providerId }); return { registration, membershipId: result.membershipId };
}
function stage(f: Owner, registration: Registration, path: string, body: Record<string, unknown>, wire: Record<string, unknown>, authorization?: string) {
	// Every stage retains the SAME registration helper's original three-second
	// expiry, including all retries. Elapsed setup/approval/readback MUST FAIL;
	// no Assignment, Lease, availability or productive window is created.
	const now = new Date(), payload = { ...registration.inputs.payload, path, bodySha256: sha256(canonicalJson(body)), issuedAt: now.toISOString(), jti: randomUUID() };
	const original = structuredClone({ payload, body, wire }); const key = z.string().parse(body.idempotencyKey);
	const post = (fresh = false) => {
		assert.ok(Date.now() < Date.parse(payload.expiresAt), 'Original stage proof expired; no retry extension is allowed');
		const claims = fresh ? { ...payload, jti: randomUUID() } : payload;
		return f.app.request(new Request(`http://localhost${path}`, { method: 'POST', headers: { 'content-type': 'application/json', 'idempotency-key': key, ...(authorization ? { authorization } : {}) }, body: JSON.stringify({ ...wire, proof: registration.inputs.proof(claims) }) }));
	};
	return { payload, post, unchanged() { expect({ payload, body, wire }).toEqual(original); expect(Date.now() < Date.parse(payload.expiresAt)).toBe(true); } };
}
const exchangeStage = (f: Owner, registration: Registration) => stage(f, registration, restPath(CONTROL_PLANE_OPERATIONS.providers.exchangeCredential.descriptor.rest).replace('{requestId}', registration.request.id), { requestId: registration.request.id, idempotencyKey: 'bootstrap-exchange' }, {});

