it('genuine enrolled PostgreSQL overlapping first exchanges share one credential authorization and audit with two independently blocked native transactions and exact replay history', async () => {
	const f = await dependencyOperator(); let holder: PoolClient | undefined; const pending: Promise<Response>[] = [], settled: boolean[] = [];
	try {
		const { registration, membershipId } = await approved(f), before = await f.state();
		const authority = rows(before, 'capacity_provider_credential_issuance_authorizations').find(row => row.membership_id === membershipId)!; expect(authority).toMatchObject({ generation: 1, status: 'pending', issued_credential_id: null });
		// ONLY fresh-DB transaction locks and trigger; no service/query/SQL mock,
		// supplied enrollment row, other database, server signal or new runner.
		await f.left.pool.query('CREATE FUNCTION bootstrap_exchange_barrier() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_advisory_xact_lock(393,239); RETURN NEW; END $$');
		await f.left.pool.query("CREATE TRIGGER bootstrap_exchange_barrier BEFORE UPDATE ON capacity_provider_credential_issuance_authorizations FOR EACH ROW WHEN (OLD.status='pending' AND NEW.status='issued') EXECUTE FUNCTION bootstrap_exchange_barrier()");
		holder = await f.right.pool.connect(); const owned = await holder.query<{ name: string; pid: number }>('SELECT current_database() AS name, pg_backend_pid() AS pid'); expect(owned.rows).toHaveLength(1); const held = owned.rows[0]!; expect(held.name).toBe(f.name); expect(Number.isSafeInteger(held.pid) && held.pid > 0).toBe(true);
		await holder.query('BEGIN'); await holder.query('SELECT pg_advisory_xact_lock(393,239)');
		const exchange = exchangeStage(f, registration);
		for (const fresh of [false, true]) { const index = pending.length, promise = Promise.resolve(exchange.post(fresh)); settled.push(false); pending.push(promise); void promise.then(() => { settled[index] = true; }, () => { settled[index] = true; }); }
		let observed: Array<{ pid: number; blockers: number[] }> = [];
		await eventObserved(async () => {
			assert.ok(Date.now() < Date.parse(exchange.payload.expiresAt), 'Original exchange expiry elapsed before native overlap observation');
			observed = (await f.right.pool.query<{ pid: number; blockers: number[] }>("SELECT pid, pg_blocking_pids(pid) AS blockers FROM pg_stat_activity WHERE datname=current_database() AND backend_type='client backend' AND wait_event_type='Lock' AND query LIKE '%UPDATE capacity_provider_credential_issuance_authorizations%' ORDER BY pid")).rows;
			const first = observed.find(row => row.blockers.includes(held.pid)); return observed.length === 2 && Boolean(first && observed.some(row => row.pid !== first.pid && row.blockers.includes(first.pid)));
		});
		expect(new Set(observed.map(row => row.pid)).size).toBe(2); for (const row of observed) expect(Number.isSafeInteger(row.pid) && row.pid > 0 && row.pid !== held.pid).toBe(true);
		const firstBlocked = observed.find(row => row.blockers.includes(held.pid))!; expect(firstBlocked.blockers).toEqual([held.pid]); expect(observed.find(row => row.pid !== firstBlocked.pid)!.blockers).toEqual([firstBlocked.pid]); expect(settled).toEqual([false, false]);
		const blocked = await f.state(); unchangedExcept(before, blocked, ['capacity_provider_proof_nonces']); const nonces = additions(before, blocked, 'capacity_provider_proof_nonces', 2); expect(nonces.map(row => row.jti)).toContain(exchange.payload.jti); expect(new Set(nonces.map(row => row.jti)).size).toBe(2); for (const nonce of nonces) expect(nonce).toMatchObject({ provider_fingerprint: exchange.payload.providerFingerprint, expires_at: exchange.payload.expiresAt }); expect(await f.state(f.right)).toEqual(blocked);
		await holder.query('ROLLBACK'); holder.release(); holder = undefined;
		// Await ORIGINAL promises; a losing 500/409/rejection is never relabeled
		// an idempotent success. The desired same-key contract requires BOTH200.
		const responses = await Promise.all(pending), outputs = await Promise.all(responses.map(response => output(response, CONTROL_PLANE_OPERATIONS.providers.exchangeCredential)));
		const credentialValue = z.string().min(1).parse(outputs[0]!.credential); expect(credentialValue === outputs[1]!.credential).toBe(true); expect({ ...outputs[0], credential: undefined }).toEqual({ ...outputs[1], credential: undefined }); expect({ ...outputs[0], credential: undefined }).toMatchObject({ membershipId, teamId: 'team', providerId: registration.request.providerId, issuanceGeneration: 1, status: 'active', scopes: [...PROVIDER_MEMBERSHIP_SCOPES] });
		const credentialId = z.string().parse(outputs[0]!.id), after = await f.state(); unchangedExcept(blocked, after, ['capacity_provider_credential_issuance_authorizations', 'capacity_provider_team_credentials', 'capacity_audit_events']);
		changedRow(blocked, after, 'capacity_provider_credential_issuance_authorizations', String(authority.id), { status: 'issued', issued_credential_id: credentialId }, ['status', 'issued_credential_id', 'updated_at']);
		expect(additions(blocked, after, 'capacity_provider_team_credentials', 1)[0]).toMatchObject({ id: credentialId, membership_id: membershipId, capacity_provider_id: registration.request.providerId, issuance_authorization_id: authority.id, issuance_generation: 1, issue_idempotency_key: 'bootstrap-exchange', status: 'active' }); expect(additions(blocked, after, 'capacity_audit_events', 1)[0]).toMatchObject({ action: 'provider-credential.issued', resource_id: credentialId, request_id: registration.request.id, membership_id: membershipId, idempotency_key: 'bootstrap-exchange' }); expect(await f.state(f.right)).toEqual(after);
		expect(JSON.stringify(after).includes(credentialValue)).toBe(false);
		expect((await f.right.pool.query("SELECT pid FROM pg_locks WHERE locktype='advisory' AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND classid=393 AND objid=239 AND objsubid=2")).rows).toEqual([]);
		await f.left.pool.query('DROP TRIGGER bootstrap_exchange_barrier ON capacity_provider_credential_issuance_authorizations'); await f.left.pool.query('DROP FUNCTION bootstrap_exchange_barrier()');
		expect((await f.right.pool.query("SELECT tgname FROM pg_trigger WHERE tgname='bootstrap_exchange_barrier'")).rows).toEqual([]); expect((await f.right.pool.query("SELECT proname FROM pg_proc WHERE proname='bootstrap_exchange_barrier' AND pronamespace='public'::regnamespace")).rows).toEqual([]);
		await denied(await exchange.post(), 409, 'provider_proof_replayed'); expect(await f.state()).toEqual(after);
		const replay = await output(await exchange.post(true), CONTROL_PLANE_OPERATIONS.providers.exchangeCredential); expect(replay.credential === outputs[0]!.credential).toBe(true); expect({ ...replay, credential: undefined }).toEqual({ ...outputs[0], credential: undefined });
		const replayed = await f.state(); unchangedExcept(after, replayed, ['capacity_provider_proof_nonces']); additions(after, replayed, 'capacity_provider_proof_nonces', 1); expect(await f.state(f.right)).toEqual(replayed); exchange.unchanged();
	} finally {
		try { if (holder) await holder.query('ROLLBACK'); await eventObserved(() => settled.every(Boolean)); await Promise.allSettled(pending); }
		finally { try { holder?.release(); } finally { await f.close(); } }
	}
});

it('genuine enrolled PostgreSQL late credential audit failure retains issued authority and secret custody then fresh nonce replay recovers one missing audit without hiding the failed footprint', async () => {
	const f = await dependencyOperator();
	try {
		const { registration, membershipId } = await approved(f), before = await f.state(), authority = rows(before, 'capacity_provider_credential_issuance_authorizations').find(row => row.membership_id === membershipId)!;
		await f.left.pool.query("CREATE FUNCTION bootstrap_credential_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'native bootstrap credential audit interruption' USING ERRCODE='P0001'; END $$");
		await f.left.pool.query("CREATE TRIGGER bootstrap_credential_audit_failure BEFORE INSERT ON capacity_audit_events FOR EACH ROW WHEN (NEW.action='provider-credential.issued') EXECUTE FUNCTION bootstrap_credential_audit_failure()");
		const exchange = exchangeStage(f, registration), failed = await exchange.post(); expect(failed.status).toBe(500);
		const failure = await f.state(); unchangedExcept(before, failure, ['capacity_provider_credential_issuance_authorizations', 'capacity_provider_team_credentials', 'capacity_provider_proof_nonces']);
		const credential = additions(before, failure, 'capacity_provider_team_credentials', 1)[0]!; expect(credential).toMatchObject({ membership_id: membershipId, issuance_authorization_id: authority.id, issuance_generation: 1, status: 'active', issue_idempotency_key: 'bootstrap-exchange' }); expect(credential.revealed_at).toBeTypeOf('string'); const credentialId = z.string().parse(credential.id);
		changedRow(before, failure, 'capacity_provider_credential_issuance_authorizations', String(authority.id), { status: 'issued', issued_credential_id: credentialId }, ['status', 'issued_credential_id', 'updated_at']); expect(additions(before, failure, 'capacity_provider_proof_nonces', 1)[0]).toMatchObject({ jti: exchange.payload.jti, expires_at: exchange.payload.expiresAt, provider_fingerprint: exchange.payload.providerFingerprint }); expect(await f.state(f.right)).toEqual(failure);
		await f.left.pool.query('DROP TRIGGER bootstrap_credential_audit_failure ON capacity_audit_events'); await f.left.pool.query('DROP FUNCTION bootstrap_credential_audit_failure()');
		expect((await f.right.pool.query("SELECT tgname FROM pg_trigger WHERE tgname='bootstrap_credential_audit_failure'")).rows).toEqual([]); expect((await f.right.pool.query("SELECT proname FROM pg_proc WHERE proname='bootstrap_credential_audit_failure' AND pronamespace='public'::regnamespace")).rows).toEqual([]);
		await denied(await exchange.post(), 409, 'provider_proof_replayed'); expect(await f.state()).toEqual(failure);
		const replay = await output(await exchange.post(true), CONTROL_PLANE_OPERATIONS.providers.exchangeCredential); expect(replay.id).toBe(credentialId); expect({ ...replay, credential: undefined }).toMatchObject({ membershipId, teamId: 'team', providerId: registration.request.providerId, issuanceGeneration: 1, status: 'active', scopes: [...PROVIDER_MEMBERSHIP_SCOPES] }); const credentialValue = z.string().min(1).parse(replay.credential);
		const recovered = await f.state(); unchangedExcept(failure, recovered, ['capacity_provider_proof_nonces', 'capacity_audit_events']); additions(failure, recovered, 'capacity_provider_proof_nonces', 1); expect(additions(failure, recovered, 'capacity_audit_events', 1)[0]).toMatchObject({ action: 'provider-credential.issued', actor_type: 'provider-identity', actor_id: exchange.payload.providerFingerprint, resource_type: 'provider-team-credential', resource_id: credentialId, request_id: registration.request.id, membership_id: membershipId, idempotency_key: 'bootstrap-exchange' }); expect(await f.state(f.right)).toEqual(recovered); expect(JSON.stringify(recovered).includes(credentialValue)).toBe(false);
		const repeated = await output(await exchange.post(true), CONTROL_PLANE_OPERATIONS.providers.exchangeCredential); expect(repeated.credential === credentialValue).toBe(true); expect({ ...repeated, credential: undefined }).toEqual({ ...replay, credential: undefined });
		const repeatedState = await f.state(); unchangedExcept(recovered, repeatedState, ['capacity_provider_proof_nonces']); additions(recovered, repeatedState, 'capacity_provider_proof_nonces', 1); expect(await f.state(f.right)).toEqual(repeatedState); exchange.unchanged();
	} finally { await f.close(); }
});
